<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';import {CompanySocialClient,CompanySocialError,socialAuthorizationUrl,type SocialConnectionSnapshot,type SocialAssetPage,type SocialDelegation,type DelegationSelection} from './company-social-client';import '../automations/automations.css';
 export let platform:'facebook'|'instagram'|'both'='both';export let companyId:string;export let actorId:string;export let companyName='this company';export let conversationId='';export let accessSignal:AbortSignal;
 const dispatch=createEventDispatcher<{close:void;denied:{status:number};changed:{companyId:string}}>();let mounted=false,scope='',watched:AbortSignal|undefined,client:CompanySocialClient|undefined,generation=0,session='',loading=true,busy=false,error='',notice='',snapshot:SocialConnectionSnapshot|null=null,assets:SocialAssetPage[]=[],selectedPages:string[]=[],instagram:Record<string,string[]>={},authorization='',review=false,consent=false,revoking:SocialDelegation|null=null;
 $: ownAccount=!!snapshot&&snapshot.account.status==='CONNECTED'&&snapshot.account.ownedByCurrentUser&&snapshot.account.ownerUserId===actorId;
 $: ownActive=snapshot?.delegations.filter(d=>d.status==='ACTIVE'&&d.ownerUserId===actorId)||[];
 $: canSelect=ownAccount&&snapshot?.actions.canDelegate===true&&ownActive.length<=1;
 $: validSelection=choices.length===1&&choices.every(p=>p.canPublish&&(instagram[p.id]||[]).every(id=>p.instagramAccounts.some(a=>a.id===id&&a.canPublish)));
 $: choices=assets.filter(p=>selectedPages.includes(p.id));
 $: if(mounted&&(scope!==companyId+'\0'+actorId+'\0'+conversationId||watched!==accessSignal)){reset();scope=companyId+'\0'+actorId+'\0'+conversationId;watched=accessSignal;watched.addEventListener('abort',lost,{once:true});if(watched.aborted)lost();else{session=localStorage.getItem('token')||'';client=new CompanySocialClient(companyId,()=>localStorage.getItem('token')||'',watched);void load();}}
 function reset(){generation++;client?.close();client=undefined;watched?.removeEventListener('abort',lost);snapshot=null;assets=[];selectedPages=[];instagram={};authorization='';review=false;consent=false;revoking=null;loading=true;busy=false;error='';notice='';}
 function lost(){reset();loading=false;dispatch('close');}
 function fail(cause:unknown){if(cause instanceof CompanySocialError&&(cause.status===401||cause.status===403)){lost();dispatch('denied',{status:cause.status});return;}error=cause instanceof Error?cause.message:'The company publishing connection could not be checked.';}
 async function load(){if(!client)return;const current=client,n=generation;loading=true;error='';try{const value=await current.connections();if(n!==generation)return;snapshot=value;authorization='';review=false;consent=false;revoking=null;if(value.account.status==='CONNECTED'&&value.account.ownedByCurrentUser&&value.account.ownerUserId===actorId&&value.actions.canDelegate){const pages=await current.assets();if(n!==generation)return;assets=pages;const active=value.delegations.filter(d=>d.status==='ACTIVE'&&d.ownerUserId===actorId);selectedPages=active.length===1?active[0].pages.filter(p=>pages.some(a=>a.id===p.pageId&&a.pageConnectionId===p.pageConnectionId)).map(p=>p.pageId):[];instagram={};if(active.length===1)for(const page of active[0].pages){const asset=pages.find(p=>p.id===page.pageId);instagram[page.pageId]=page.instagramAccountIds.filter(id=>asset?.instagramAccounts.some(a=>a.id===id));}}else{assets=[];selectedPages=[];instagram={};}}catch(e){if(n===generation)fail(e);}finally{if(n===generation)loading=false;}}
 async function connect(){if(!client||busy||!conversationId||!snapshot?.actions.canConnect||!snapshot.capabilities.oauthConfigured)return;const current=client,n=generation;busy=true;error='';try{const value=await current.connect(conversationId);if(n===generation)authorization=value.authorizationUrl;}catch(e){if(n===generation)fail(e);}finally{if(n===generation)busy=false;}}
 function togglePage(id:string){review=false;consent=false;if(selectedPages.includes(id))selectedPages=[id];if(!selectedPages.includes(id))instagram={...instagram,[id]:[]};}
 function selectInstagram(pageId:string,id:string,checked:boolean){const current=instagram[pageId]||[];instagram={...instagram,[pageId]:checked?[...new Set([...current,id])]:current.filter(v=>v!==id)};review=false;consent=false;}
 async function delegate(){if(!client||busy||!canSelect||!conversationId||!consent||!validSelection)return;const current=client,n=generation;const pages:DelegationSelection[]=choices.map(p=>({pageId:p.id,pageConnectionId:p.pageConnectionId,instagramAccountIds:(instagram[p.id]||[]).filter(id=>p.instagramAccounts.some(a=>a.id===id&&a.canPublish))}));busy=true;error='';try{const value=await current.delegate(conversationId,pages,ownActive[0]?.revision);if(n!==generation)return;if(value.ownerUserId!==actorId)throw new CompanySocialError(0,'The reviewed account owner could not be confirmed.');await load();if(n===generation){notice='The exact reviewed company destinations were saved. Publishing follows their current permissions and approval rules.';dispatch('changed',{companyId});}}catch(e){if(n===generation)fail(e);}finally{if(n===generation)busy=false;}}
 async function revoke(){if(!client||!revoking||busy||!snapshot?.actions.canRevoke)return;const target=revoking,current=client,n=generation;busy=true;error='';try{await current.revoke(target);if(n!==generation)return;await load();if(n===generation){notice='Company access revoked. The owner’s publishing account connection is retained.';dispatch('changed',{companyId});}}catch(e){if(n===generation)fail(e);}finally{if(n===generation)busy=false;}}
 function checkSession(){if(client&&session!==(localStorage.getItem('token')||''))lost();}function focus(){checkSession();if(client&&!busy)void load();}function storage(e:StorageEvent){if(e.key==='token'||e.key===null)lost();}
 onMount(()=>{mounted=true;window.addEventListener('storage',storage);window.addEventListener('focus',focus);const timer=setInterval(checkSession,500);return()=>clearInterval(timer);});onDestroy(()=>{reset();window.removeEventListener('storage',storage);window.removeEventListener('focus',focus);});
</script>
<section class="starli-automations social" aria-label="Company Facebook and Instagram connections"><header class="sa-heading"><div><span class="sa-eyebrow">STARLI INTEGRATIONS</span><h2>Facebook & Instagram</h2><p class="sa-muted">Connect your own publishing account, then explicitly select which destinations this company may use.</p></div><button disabled={busy||loading||loading} on:click={()=>void load()}>Refresh</button></header>{#if error}<p class="sa-error" role="alert">{error}</p>{/if}{#if notice}<p class="sa-muted" role="status">{notice}</p>{/if}{#if loading&&!snapshot}<p class="sa-muted" role="status">Checking company publishing connections…</p>{/if}
 {#if snapshot}<div class="provider-pair"><div class="provider"><span class="provider-icon facebook" aria-hidden="true">f</span><div><h3>Facebook Pages</h3><p class="sa-muted">Choose exact company destinations</p></div></div><div class="provider"><span class="provider-icon" aria-hidden="true"><svg width="21" height="21" viewBox="0 0 24 24" fill="none"><rect x="4" y="4" width="16" height="16" rx="5" stroke="currentColor" stroke-width="1.6"/><circle cx="12" cy="12" r="3.7" stroke="currentColor" stroke-width="1.6"/><circle cx="17.3" cy="6.8" r="1" fill="currentColor"/></svg></span><div><h3>Instagram accounts</h3><p class="sa-muted">Accounts linked to selected Pages</p></div></div></div>
 {#if snapshot.account.status==='CLIENT_NOT_CONFIGURED'||!snapshot.capabilities.oauthConfigured}<p class="sa-warning" role="status">Secure publishing-account sign-in is not configured on this deployment. No account or company permission has been created.</p>{:else if !ownAccount}<div class="sa-note"><strong>Connect your own publishing account</strong><p class="sa-muted">Account access is personal until you explicitly delegate selected Facebook Pages and Instagram accounts to {companyName}.</p>{#if authorization&&socialAuthorizationUrl(authorization)}<a class="sa-primary sa-link" href={socialAuthorizationUrl(authorization)||undefined} target="_blank" rel="noopener noreferrer">Continue secure account consent ↗</a><button disabled={busy||loading} on:click={()=>void load()}>I’ve finished connecting</button>{:else}<button class="sa-primary" disabled={busy||loading||!snapshot.actions.canConnect||!conversationId} on:click={connect}>Connect my publishing account</button>{/if}</div>{:else}<p class="sa-muted">Your publishing account is connected. Company access requires a separate destination review below.</p>{/if}
 {#if !conversationId}<p class="sa-warning">Open this connection card from the original company conversation to begin or change access.</p>{/if}{#if !snapshot.capabilities.publishingReady}<p class="sa-warning">Company publishing is not executable yet. A connected account or saved destination does not mean posting is enabled.</p>{/if}
 {#if ownAccount&&canSelect}<div class="assets"><h3>Select company destinations</h3><p class="sa-muted">Choose one Facebook Page and its linked Instagram accounts for this company connection.</p><p class="sa-muted">{platform==='instagram'?'Choose the Facebook Page linked to your Instagram account, then select the exact Instagram destination.':'Only your freshly authorized Pages and linked Instagram accounts are listed.'}</p>{#each assets as page}<div class="page"><label class="choice"><input type="checkbox" value={page.id} bind:group={selectedPages} disabled={busy||loading||!page.canPublish&&!selectedPages.includes(page.id)} on:change={()=>togglePage(page.id)}/><span><strong>{page.name}</strong><small>Facebook Page · {page.id}{!page.canPublish?' · publishing permission unavailable':''}</small></span></label>{#if selectedPages.includes(page.id)}<div class="instagram-accounts">{#each page.instagramAccounts as account}<label class="choice"><input type="checkbox" checked={(instagram[page.id]||[]).includes(account.id)} disabled={busy||loading||!account.canPublish&&!(instagram[page.id]||[]).includes(account.id)} on:change={event=>selectInstagram(page.id,account.id,event.currentTarget.checked)}/><span>{account.name}<small>Instagram · {account.id}{!account.canPublish?' · publishing permission unavailable':''}</small></span></label>{:else}<p class="sa-muted">No authorized Instagram account is linked to this Page.</p>{/each}</div>{/if}</div>{:else}<p class="sa-muted">No authorized publishing Pages were returned for your account.</p>{/each}<button class="sa-primary" disabled={busy||loading||!conversationId||!validSelection} on:click={()=>{review=true;consent=false;}}>Review company access</button></div>{/if}
 {#if review&&canSelect}<div class="sa-confirm"><h3>Allow these destinations for {companyName}?</h3><p class="sa-muted">This uses your account only for the exact selected destinations. Publishing actions and ongoing loop rules still require their own authorization.</p><ul>{#each choices as page}<li>{page.name} · Facebook{#each page.instagramAccounts.filter(a=>(instagram[page.id]||[]).includes(a.id)) as account}<span> · {account.name} on Instagram</span>{/each}</li>{/each}</ul><label class="choice"><input type="checkbox" bind:checked={consent} disabled={busy||loading}/><span>I allow this company’s authorized bots to use these exact destinations.</span></label><div class="sa-actions"><button disabled={busy||loading} on:click={()=>review=false}>Keep private</button><button class="sa-primary" disabled={busy||loading||!consent} on:click={delegate}>Confirm company access</button></div></div>{/if}
 <h3 class="subheading">Saved company access</h3>{#each snapshot.delegations as delegation}<article class="delegation"><div class="sa-heading"><strong>{delegation.status==='ACTIVE'?'Company access saved':'Company access revoked'}</strong><span class="sa-badge">revision {delegation.revision}</span></div>{#each delegation.pages as page}<p class="sa-muted">{page.name} · Facebook Page {page.pageId}{page.instagramAccountIds.length?' · '+page.instagramAccountIds.length+' Instagram account(s)':''}</p>{/each}<p class="sa-reference">Account owner {delegation.ownerUserId}</p>{#if delegation.status==='ACTIVE'&&snapshot.actions.canRevoke}<button class="sa-danger" disabled={busy||loading} on:click={()=>revoking=delegation}>Revoke company access</button>{/if}{#if revoking?.id===delegation.id}<div class="sa-confirm"><strong>Revoke these company destinations?</strong><p class="sa-muted">Company bots and loops lose this delegation. The owner’s personal connection is retained.</p><div class="sa-actions"><button disabled={busy||loading} on:click={()=>revoking=null}>Keep access</button><button class="sa-danger" disabled={busy||loading} on:click={revoke}>Confirm revocation</button></div></div>{/if}</article>{:else}<p class="sa-muted">No publishing account has been delegated to this company.</p>{/each}{/if}
</section>
<style>.social{width:100%;max-width:900px;padding:24px;color:#17243f;overflow:auto}.provider-pair{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:20px 0}.provider{display:flex;align-items:center;gap:12px;padding:17px;border:1px solid #e6ebf4;border-radius:10px}.provider-icon{display:grid;place-items:center;flex-shrink:0;width:36px;height:36px;border-radius:9px;background:#f2effb;color:#895fa8}.provider-icon.facebook{font-size:27px;font-weight:650;background:#edf3ff;color:#3466f6}.provider .sa-muted{font-size:10px;margin-bottom:0}.social .sa-link{display:inline-block;margin-right:8px}.assets{margin:24px 0}.page{border:1px solid #e6ebf4;border-radius:9px;padding:12px 14px;margin:12px 0}.choice{display:flex;align-items:flex-start;gap:10px;line-height:1.8;font-size:12px;margin:9px 0;cursor:pointer}.choice input{accent-color:#3466f6;margin-top:4px}.choice small{display:block;font-size:10px;color:#71809a;overflow-wrap:anywhere}.instagram-accounts{padding:3px 0 2px 26px;border-top:1px solid #e6ebf4;margin-top:12px}.social ul{font-size:12px;line-height:1.9;color:#71809a;padding-left:18px}.subheading{margin-top:28px!important}.delegation{border-top:1px solid #e6ebf4;padding:18px 0}.delegation>.sa-reference{margin:8px 0 12px}.social header{gap:18px}.social .sa-warning{overflow-wrap:anywhere}@media(max-width:600px){.social{padding:18px}.provider-pair{grid-template-columns:1fr}.social header{flex-direction:column}.provider{padding:14px}.social .sa-link{margin:10px 0}}</style>
